"use client";

import { useEffect, useRef, useState } from "react";

export default function WaitingGame() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationId: number;
    
    // Game variables
    let birdY = canvas.height / 2;
    let velocity = 0;
    const gravity = 0.45;
    const jump = -7.5;
    let pipes: { x: number; top: number; bottom: number }[] = [];
    const pipeWidth = 40;
    const gap = 130;
    let frame = 0;
    let currentScore = 0;

    const resetGame = () => {
      birdY = canvas.height / 2;
      velocity = 0;
      pipes = [];
      frame = 0;
      currentScore = 0;
      setScore(0);
    };

    const loop = () => {
      if (!isPlaying) {
        // Draw idle screen
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#6366f1";
        ctx.beginPath();
        ctx.arc(40, birdY, 12, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#ffffff";
        ctx.font = "bold 16px Inter";
        ctx.textAlign = "center";
        ctx.fillText("Tap to Start & Jump!", canvas.width / 2, canvas.height / 2);
        return;
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Bird physics
      velocity += gravity;
      birdY += velocity;

      // Add pipes
      if (frame % 90 === 0) {
        const top = Math.random() * (canvas.height - gap - 40) + 20;
        pipes.push({ x: canvas.width, top, bottom: top + gap });
      }

      // Draw pipes & collision
      ctx.fillStyle = "#22c55e";
      for (let i = 0; i < pipes.length; i++) {
        const p = pipes[i];
        p.x -= 3.5;
        
        ctx.fillRect(p.x, 0, pipeWidth, p.top);
        ctx.fillRect(p.x, p.bottom, pipeWidth, canvas.height - p.bottom);

        // Collision
        if (
          40 + 10 > p.x && 40 - 10 < p.x + pipeWidth &&
          (birdY - 10 < p.top || birdY + 10 > p.bottom)
        ) {
          setIsPlaying(false);
          if (currentScore > highScore) setHighScore(currentScore);
        }

        // Score
        if (p.x === 40) {
          currentScore++;
          setScore(currentScore);
        }
      }

      // Remove offscreen pipes
      if (pipes.length > 0 && pipes[0].x < -pipeWidth) {
        pipes.shift();
      }

      // Floor / Ceiling collision
      if (birdY > canvas.height || birdY < 0) {
        setIsPlaying(false);
        if (currentScore > highScore) setHighScore(currentScore);
      }

      // Draw Bird
      ctx.fillStyle = "#facc15";
      ctx.beginPath();
      ctx.arc(40, birdY, 12, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#ca8a04";
      ctx.lineWidth = 2;
      ctx.stroke();

      frame++;
      animationId = requestAnimationFrame(loop);
    };

    if (isPlaying) {
      animationId = requestAnimationFrame(loop);
    } else {
      loop(); // Draw initial frame
    }

    const handleInput = (e: Event) => {
      e.preventDefault();
      if (!isPlaying) {
        resetGame();
        setIsPlaying(true);
      }
      velocity = jump;
    };

    canvas.addEventListener("touchstart", handleInput, { passive: false });
    canvas.addEventListener("mousedown", handleInput);

    return () => {
      cancelAnimationFrame(animationId);
      canvas.removeEventListener("touchstart", handleInput);
      canvas.removeEventListener("mousedown", handleInput);
    };
  }, [isPlaying, highScore]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px', marginTop: '16px', width: '100%' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', width: '320px', fontWeight: 800, color: '#a1a1aa', fontSize: '0.9rem' }}>
        <span>Score: <span style={{ color: '#fff' }}>{score}</span></span>
        <span>Best: <span style={{ color: '#fff' }}>{highScore}</span></span>
      </div>
      <canvas
        ref={canvasRef}
        width={320}
        height={400}
        style={{
          background: '#0f172a',
          borderRadius: '16px',
          border: '2px solid rgba(255,255,255,0.1)',
          boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
          cursor: 'pointer',
          touchAction: 'none'
        }}
      />
      <p style={{ color: '#667085', fontSize: '0.8rem', marginTop: '8px' }}>Waiting for host to start...</p>
    </div>
  );
}
